// Pine One case study deck — builds a new page of 1920×1080 slides. Never edits existing pages.
const BG = "";

const C = {
  ink: "#1A2E05", body: "#3F4A2E", muted: "#6B7558", accent: "#4D7C0F",
  lime: "#ECFCCB", line: "#E2E7D5", bg: "#F7F8F1", card: "#FFFFFF",
  phFill: "#EEF2E2", phStroke: "#9DAF7E", white: "#FFFFFF",
};
const W = 1920, H = 1080, PAD = 96, INNER = W - PAD * 2;

const hex = (h) => ({ r: parseInt(h.slice(1, 3), 16) / 255, g: parseInt(h.slice(3, 5), 16) / 255, b: parseInt(h.slice(5, 7), 16) / 255 });
const solid = (h, opacity = 1) => [{ type: "SOLID", color: hex(h), opacity }];
let FAM = "Inter";
let bgHash = null;
const imageFill = () => [{ type: "IMAGE", imageHash: bgHash, scaleMode: "FILL" }];

function txt(str, size, weight, color, width) {
  const t = figma.createText();
  t.fontName = { family: FAM, style: weight };
  t.characters = str;
  t.fontSize = size;
  t.lineHeight = { value: Math.round(size * (size >= 40 ? 1.12 : 1.4)), unit: "PIXELS" };
  if (size >= 40) t.letterSpacing = { value: -1.5, unit: "PERCENT" };
  t.fills = solid(color);
  if (width) { t.resize(width, t.height); t.textAutoResize = "HEIGHT"; }
  return t;
}

function stack(dir, gap, width, opts = {}) {
  const f = figma.createFrame();
  f.name = opts.name || (dir === "VERTICAL" ? "Stack" : "Row");
  f.layoutMode = dir;
  f.itemSpacing = gap;
  f.fills = opts.fill ? solid(opts.fill, opts.opacity ?? 1) : [];
  const p = opts.pad ?? 0;
  f.paddingTop = f.paddingBottom = opts.padY ?? p;
  f.paddingLeft = f.paddingRight = opts.padX ?? p;
  if (opts.radius) f.cornerRadius = opts.radius;
  if (opts.stroke) { f.strokes = solid(opts.stroke); f.strokeWeight = 1; }
  if (dir === "VERTICAL") { f.primaryAxisSizingMode = "AUTO"; f.counterAxisSizingMode = "FIXED"; f.resize(width, 10); }
  else { f.primaryAxisSizingMode = "FIXED"; f.counterAxisSizingMode = "AUTO"; f.resize(width, 10); }
  return f;
}

function add(parent, child, stretch = true) {
  parent.appendChild(child);
  if (stretch) child.layoutAlign = "STRETCH";
  return child;
}

const isFill = (s) => /\[To fill/.test(s);

function card(item, width) {
  const f = stack("VERTICAL", 10, width, { name: "Card", fill: C.card, pad: 28, radius: 16, stroke: C.line });
  if (item.k) add(f, txt(item.k.toUpperCase(), 14, "Semi Bold", C.accent, width - 56));
  if (item.h) add(f, txt(item.h, 24, "Semi Bold", C.ink, width - 56));
  if (item.b) add(f, txt(item.b, 19, "Regular", isFill(item.b) ? C.accent : C.body, width - 56));
  if (isFill(item.h || "") || isFill(item.b || "")) { f.dashPattern = [8, 6]; f.strokes = solid(C.phStroke); f.fills = solid(C.phFill); }
  return f;
}

function placeholder(label, width, height) {
  const f = figma.createFrame();
  f.name = "Placeholder";
  f.resize(width, height);
  f.fills = solid(C.phFill);
  f.strokes = solid(C.phStroke);
  f.dashPattern = [10, 8];
  f.strokeWeight = 2;
  f.cornerRadius = 20;
  f.layoutMode = "VERTICAL";
  f.primaryAxisAlignItems = "CENTER";
  f.counterAxisAlignItems = "CENTER";
  f.primaryAxisSizingMode = "FIXED";
  f.counterAxisSizingMode = "FIXED";
  f.itemSpacing = 8;
  f.paddingLeft = f.paddingRight = 40;
  const a = txt("＋  TO ADD", 14, "Semi Bold", C.accent);
  const b = txt(label, 20, "Medium", C.body, Math.min(width - 80, 640));
  b.textAlignHorizontal = "CENTER";
  f.appendChild(a); f.appendChild(b);
  return f;
}

function block(b, width) {
  if (b.heading) return txt(b.heading, 22, "Semi Bold", C.ink, width);
  if (b.ph) return placeholder(b.ph, width, b.h || 560);
  if (b.bullets) {
    const s = stack("VERTICAL", 18, width, { name: "Bullets" });
    for (const line of b.bullets) {
      const r = stack("HORIZONTAL", 16, width, { name: "Bullet" });
      const dot = figma.createEllipse(); dot.resize(10, 10); dot.fills = solid(C.accent);
      const holder = figma.createFrame(); holder.resize(10, 30); holder.fills = []; holder.appendChild(dot); dot.y = 11;
      r.appendChild(holder);
      r.appendChild(txt(line, 24, "Regular", isFill(line) ? C.accent : C.body, width - 26));
      add(s, r);
    }
    return s;
  }
  if (b.cards) {
    const n = b.cols || b.cards.length, gap = 20;
    const cw = Math.floor((width - gap * (n - 1)) / n);
    const s = stack("VERTICAL", gap, width, { name: "Cards" });
    for (let i = 0; i < b.cards.length; i += n) {
      const r = stack("HORIZONTAL", gap, width, { name: "Card row" });
      for (const item of b.cards.slice(i, i + n)) { const c = card(item, cw); r.appendChild(c); c.layoutAlign = "STRETCH"; }
      add(s, r);
    }
    return s;
  }
  if (b.steps) {
    const n = b.steps.length, gap = 16;
    const cw = Math.floor((width - gap * (n - 1)) / n);
    const r = stack("HORIZONTAL", gap, width, { name: "Steps" });
    b.steps.forEach((st, i) => { const c = card({ k: String(i + 1).padStart(2, "0"), h: st[0], b: st[1] }, cw); r.appendChild(c); c.layoutAlign = "STRETCH"; });
    return r;
  }
  if (b.table) {
    const { head, rows, widths } = b.table;
    const s = stack("VERTICAL", 0, width, { name: "Table", fill: C.card, radius: 16, stroke: C.line });
    s.clipsContent = true;
    const total = widths.reduce((a, x) => a + x, 0);
    const cols = widths.map((x) => Math.floor(((width - 56) - 32 * (widths.length - 1)) * x / total));
    const mk = (cells, isHead) => {
      const r = stack("HORIZONTAL", 32, width, { name: isHead ? "Head" : "Row", padX: 28, padY: isHead ? 16 : 20, fill: isHead ? C.lime : C.card });
      cells.forEach((cell, i) => r.appendChild(txt(cell, isHead ? 15 : 19, isHead ? "Semi Bold" : i === 0 ? "Semi Bold" : "Regular", isHead ? C.accent : isFill(cell) ? C.accent : i === 0 ? C.ink : C.body, cols[i])));
      return r;
    };
    add(s, mk(head.map((x) => x.toUpperCase()), true));
    rows.forEach((row, i) => {
      if (i > 0) { const line = figma.createRectangle(); line.resize(width, 1); line.fills = solid(C.line); add(s, line); }
      add(s, mk(row, false));
    });
    return s;
  }
  if (b.callout) {
    const f = stack("HORIZONTAL", 14, width, { name: "Callout", fill: C.lime, padX: 28, padY: 20, radius: 14 });
    f.appendChild(txt(b.callout[0].toUpperCase(), 15, "Bold", C.accent));
    f.appendChild(txt(b.callout[1], 21, "Medium", C.ink, width - 300));
    f.counterAxisAlignItems = "CENTER";
    return f;
  }
  throw new Error("Unknown block " + JSON.stringify(b));
}

function footer(slide, num) {
  const l = txt("Pine One  ·  Case study", 15, "Medium", C.muted); slide.appendChild(l); l.x = PAD; l.y = H - 56;
  const r = txt(String(num).padStart(2, "0"), 15, "Medium", C.muted); slide.appendChild(r); r.x = W - PAD - r.width; r.y = H - 56;
}

function contentSlide(s, num) {
  const slide = figma.createFrame();
  slide.name = `${String(num).padStart(2, "0")} — ${s.title}`;
  slide.resize(W, H);
  slide.fills = solid(C.bg);
  slide.clipsContent = true;

  const col = stack("VERTICAL", 0, INNER, { name: "Content" });
  slide.appendChild(col); col.x = PAD; col.y = 80;

  const eyebrow = stack("HORIZONTAL", 14, INNER, { name: "Eyebrow" });
  eyebrow.counterAxisAlignItems = "CENTER";
  const mark = figma.createRectangle(); mark.resize(28, 28); mark.cornerRadius = 8; mark.fills = imageFill(); mark.name = "Mark";
  eyebrow.appendChild(mark);
  eyebrow.appendChild(txt(s.eyebrow.toUpperCase(), 15, "Semi Bold", C.accent));
  add(col, eyebrow);

  const sp = (h) => { const f = figma.createFrame(); f.resize(INNER, h); f.fills = []; f.name = "Space"; add(col, f); };
  sp(24);
  add(col, txt(s.title, 56, "Semi Bold", C.ink, 1500));
  if (s.lead) { sp(16); add(col, txt(s.lead, 24, "Regular", C.muted, 1400)); }
  sp(48);

  for (const rowSpec of s.body) {
    const parts = Array.isArray(rowSpec) ? rowSpec : [{ w: 1, blocks: [rowSpec] }];
    const gap = 48;
    const totalW = parts.reduce((a, p) => a + p.w, 0);
    const row = stack("HORIZONTAL", gap, INNER, { name: "Body row" });
    for (const p of parts) {
      const w = Math.floor((INNER - gap * (parts.length - 1)) * p.w / totalW);
      const c = stack("VERTICAL", 20, w, { name: "Column" });
      for (const b of p.blocks) add(c, block(b, w), !b.ph);
      row.appendChild(c);
    }
    add(col, row);
    sp(24);
  }
  footer(slide, num);
  return slide;
}

function frosted(width) {
  const f = stack("VERTICAL", 0, width, { name: "Panel", fill: C.white, opacity: 0.86, pad: 56, radius: 28 });
  f.effects = [{ type: "BACKGROUND_BLUR", radius: 40, visible: true }];
  return f;
}

function coverSlide(s, num) {
  const slide = figma.createFrame();
  slide.name = `${String(num).padStart(2, "0")} — Cover`;
  slide.resize(W, H); slide.fills = imageFill(); slide.clipsContent = true;
  const p = frosted(980);
  slide.appendChild(p); p.x = PAD - 16; p.y = PAD - 16;
  const iw = 980 - 112;
  const e = stack("HORIZONTAL", 14, iw, { name: "Eyebrow" }); e.counterAxisAlignItems = "CENTER";
  const mark = figma.createRectangle(); mark.resize(28, 28); mark.cornerRadius = 8; mark.fills = imageFill(); e.appendChild(mark);
  e.appendChild(txt("CASE STUDY  ·  PINE LABS", 15, "Semi Bold", C.accent));
  add(p, e);
  const g = (h) => { const f = figma.createFrame(); f.resize(iw, h); f.fills = []; add(p, f); };
  g(28);
  add(p, txt(s.title, 72, "Semi Bold", C.ink, iw));
  g(20);
  add(p, txt(s.lead, 24, "Regular", C.muted, iw));
  g(48);
  const grid = block({ cards: s.meta.map(([k, v]) => ({ k, b: v })), cols: 2 }, iw);
  add(p, grid);
  return slide;
}

function dividerSlide(s, num) {
  const slide = figma.createFrame();
  slide.name = `${String(num).padStart(2, "0")} — ${s.title}`;
  slide.resize(W, H); slide.fills = imageFill(); slide.clipsContent = true;
  const big = txt(s.act, 360, "Bold", C.white); big.opacity = 0.55; slide.appendChild(big); big.x = W - PAD - big.width; big.y = H - big.height - 40;
  const p = frosted(900);
  slide.appendChild(p); p.x = PAD - 16; p.y = H - PAD + 16;
  const iw = 900 - 112;
  add(p, txt(`ACT ${s.act}`, 15, "Semi Bold", C.accent));
  const g = (h) => { const f = figma.createFrame(); f.resize(iw, h); f.fills = []; add(p, f); };
  g(20);
  add(p, txt(s.title, 64, "Semi Bold", C.ink, iw));
  g(16);
  add(p, txt(s.lead, 24, "Regular", C.muted, iw));
  if (s.shows) { g(28); add(p, block({ callout: ["Shows", s.shows] }, iw)); }
  p.y = H - PAD + 16 - p.height;
  return slide;
}

