const COVER = {
  title: "Unifying Pine Labs' merchant platforms into one workspace",
  lead: "How I led Pine One from a one-line brief to a dev-ready platform.",
  meta: [
    ["Role", "Lead product designer"],
    ["Stakeholders", "PMs, online & in-store tech, support, business, merchants"],
    ["Domain", "B2B fintech · merchant payments"],
    ["Scope", "15 modules · web platform"],
    ["Research", "13 merchant visits + competitor benchmarks"],
    ["Handoff", "Coded prototype + design docs"],
  ],
};

(async () => {
  try {
    for (const fam of ["Inter Display", "Inter"]) {
      try {
        for (const st of ["Regular", "Medium", "Semi Bold", "Bold"]) await figma.loadFontAsync({ family: fam, style: st });
        FAM = fam; break;
      } catch (e) { /* try next */ }
    }
    bgHash = figma.createImage(figma.base64Decode(BG)).hash;

    // Goes on the existing "Case studies" page, below everything already there; falls back to a new page.
    let page = await figma.getNodeByIdAsync("538:3798");
    if (!page || page.type !== "PAGE") { page = figma.createPage(); page.name = "Pine One — Case study"; }
    await figma.setCurrentPageAsync(page);
    const maxY = page.children.reduce((m, n) => Math.max(m, n.y + n.height), 0);
    const minX = page.children.length ? page.children.reduce((m, n) => Math.min(m, n.x), Infinity) : 0;

    const GAP = 120, ROW = H + 240;
    const section = figma.createSection();
    section.name = "Pine One — Case study (draft structure)";
    page.appendChild(section);
    section.x = minX; section.y = maxY + 1200;
    section.resizeWithoutConstraints(7 * W + 6 * GAP + 400, 6 * ROW + 200);

    const created = [];
    let num = 1;
    const place = (node, row, colIdx) => { section.appendChild(node); node.x = 200 + colIdx * (W + GAP); node.y = 200 + row * ROW; created.push(node); };

    place(coverSlide(COVER, num++), 0, 0);
    ACTS.forEach((a, i) => {
      let c = 0;
      place(dividerSlide(a, num++), i + 1, c++);
      for (const s of a.slides) place(contentSlide(s, num++), i + 1, c++);
    });

    figma.currentPage.selection = created;
    figma.viewport.scrollAndZoomIntoView(created);
    figma.closePlugin(`Created ${created.length} slides in “${section.name}” on “${page.name}”.`);
  } catch (e) {
    figma.closePlugin("Deck failed: " + (e && e.message ? e.message : e));
  }
})();
